def _poster_for(title):
    """按片名哈希分配一张封面"""
    h = 0
    for ch in title:
        h = (h * 31 + ord(ch)) & 0x7FFFFFFF
    return _POSTERS[str(h % 10)]


def _pick_ua():
    return random.choice(USER_AGENTS)


def _fetch_text(url, timeout=20):
    last_err = None
    for _ in range(3):
        try:
            req = urllib.request.Request(url, headers={
                "User-Agent": _pick_ua(),
                "Accept": "text/plain,text/html,*/*",
            })
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                raw = resp.read()
            for enc in ("utf-8", "gbk", "gb2312"):
                try:
                    return raw.decode(enc)
                except Exception:
                    continue
            return raw.decode("utf-8", errors="ignore")
        except Exception as e:
            last_err = e
            time.sleep(1)
    raise RuntimeError("片单拉取失败: %s" % last_err)


def _parse_line(line):
    line = line.strip()
    if not line or "," not in line:
        return None
    idx = line.rfind(",")
    name_raw, url = line[:idx].strip(), line[idx + 1:].strip()
    if not url.startswith("http"):
        return None
    area = ""
    m = re.search(r"（([^）]*?)恐怖片）", name_raw)
    if m:
        area = m.group(1).strip().replace(" ", "")
    name = re.sub(r"（[^）]*?恐怖片）", "", name_raw).strip()
    if not name:
        name = name_raw
    return {"name": name, "area": area or "其他", "url": url, "raw": name_raw}


def _load_data(force=False):
    now = time.time()
    if not force and _cache["items"] and (now - _cache["ts"]) < CACHE_TTL:
        return _cache["items"], _cache["areas"]
    text = ""
    # 先尝试网络刷新, 失败则用内置本地片单兜底
    try:
        text = _fetch_text(DATA_URL)
    except Exception:
        pass
    if not text and os.path.exists(LOCAL_DATA):
        try:
            with open(LOCAL_DATA, "r", encoding="utf-8") as f:
                text = f.read()
        except Exception:
            pass
    if not text:
        raise RuntimeError("片单拉取失败且无本地缓存")
    items = []
    seen_areas = set()
    areas = []
    for line in text.splitlines():
        line = line.strip()
        if not line or "," not in line:
            continue
        p = _parse_line(line)
        if p:
            items.append(p)
            if p["area"] not in seen_areas:
                seen_areas.add(p["area"])
                areas.append(p["area"])
    cnt = {}
    for it in items:
        cnt[it["area"]] = cnt.get(it["area"], 0) + 1
    # 少于 3 部的地区并入"其他", 避免分类过碎
    for it in items:
        if cnt.get(it["area"], 0) < 3:
            it["area"] = "其他"
    cnt = {}
    for it in items:
        cnt[it["area"]] = cnt.get(it["area"], 0) + 1
    areas = sorted(cnt.keys(), key=lambda a: -cnt.get(a, 0))
    # "其他" 放最后
    if "其他" in areas:
        areas.remove("其他")
        areas.append("其他")
    _cache.update({"items": items, "areas": areas, "ts": now})
    return items, areas


def _is_direct_url(url):
    u = (url or "").lower().split("?")[0].split("#")[0]
    return u.endswith(VIDEO_EXTS)


def _to_vod(it, idx):
    return {
        "vod_id": "horror$%d" % idx,
        "vod_name": it["name"],
        "vod_pic": _poster_for(it["name"]),
        "vod_remarks": it["area"],
        "vod_area": it["area"],
    }


class Spider:
    def init(self, ext=""):
        pass

    def destroy(self):
        pass

    def getName(self):
        return SITE_NAME

    def homeContent(self, filter_enabled=False):
        try:
            items, areas = _load_data()
        except Exception as e:
            return {"class": [], "filters": {}, "list": [],
                    "msg": "片单加载失败: %s" % e}
        classes = [{"type_id": "all", "type_name": "全部"}]
        for a in areas:
            classes.append({"type_id": "area$%s" % a, "type_name": a})
        rec = [_to_vod(it, i) for i, it in enumerate(items[:12])]
        return {"class": classes, "filters": {}, "list": rec}

    def homeVideoContent(self):
        try:
            items, _ = _load_data()
            return {"list": [_to_vod(it, i) for i, it in enumerate(items[:12])]}
        except Exception as e:
            return {"list": [], "msg": "推荐加载失败: %s" % e}

    def categoryContent(self, tid, pg, filter_enabled=False, extend=None):
        try:
            items, _ = _load_data()
        except Exception as e:
            return {"list": [], "page": 1, "pagecount": 1, "total": 0,
                    "msg": "加载失败: %s" % e}
        if tid.startswith("area$"):
            area = tid[5:]
            filtered = [(i, it) for i, it in enumerate(items) if it["area"] == area]
        else:
            filtered = list(enumerate(items))
        pg = int(pg)
        per = 20
        total = len(filtered)
        s = (pg - 1) * per
        page_items = [_to_vod(it, i) for i, it in filtered[s:s + per]]
        return {"list": page_items, "page": pg,
                "pagecount": max(1, (total + per - 1) // per), "total": total}

    def detailContent(self, ids):
        raw = ids[0] if ids else ""
        try:
            idx = int(raw.split("$")[-1])
            items, _ = _load_data()
            it = items[idx]
        except Exception:
            return {"list": []}
        vod = {
            "vod_id": raw,
            "vod_name": it["name"],
            "vod_pic": _poster_for(it["name"]),
            "vod_area": it["area"],
            "vod_remarks": it["area"],
            "vod_content": it["raw"],
            "vod_play_from": "直链播放",
            "vod_play_url": "%s$%s" % (it["name"], it["url"]),
        }
        return {"list": [vod]}

    def searchContent(self, key, quick=False):
        try:
            items, _ = _load_data()
        except Exception as e:
            return {"list": [], "msg": "搜索失败: %s" % e}
        key = (key or "").strip().lower()
        if not key:
            return {"list": []}
        matched = [(i, it) for i, it in enumerate(items)
                   if key in it["name"].lower() or key in it["raw"].lower()]
        return {"list": [_to_vod(it, i) for i, it in matched[:50]]}

    def playerContent(self, flag, vid, vip_flags=None):
        ua = _pick_ua()
        header = {"User-Agent": ua, "Referer": "https://www.google.com/"}
        url = vid
        if "$" in vid and not vid.lstrip().startswith("http"):
            parts = vid.split("$")
            # 可能是 "horror$5" 或 "片名$http://..."
            if parts[0] == "horror":
                try:
                    idx = int(parts[-1])
                    items, _ = _load_data()
                    url = items[idx]["url"]
                except Exception:
                    pass
            else:
                url = parts[-1]
        url = (url or "").strip()
        if not url.startswith("http"):
            return {"parse": 1, "url": url, "header": header,
                    "msg": "地址异常, 转内置解析"}
        if _is_direct_url(url):
            return {"parse": 0, "playUrl": "", "url": url, "header": header}
        return {"parse": 1, "url": url, "header": header}

    def isVideoFormat(self, url):
        u = (url or "").lower().split("?")[0]
        return u.endswith(VIDEO_EXTS)

    def manualVideoCheck(self):
        return {"code": 0, "msg": "直链站源, 无需嗅探"}


if __name__ == "__main__":
    sp = Spider()
    sp.init("")
    items, areas = _load_data()
    print("共 %d 部, %d 个地区" % (len(items), len(areas)))
    print("地区:", ", ".join(areas[:10]))
